 (v_day,'Plaça de Gaudí',0,'La obra dentro del paisaje urbano.','Primera lectura del conjunto: escala, encuadre, relación con la plaza y transformación continua.',12,'Parada exterior.','Espacio urbano accesible.','Sagrada Família enmarcada por los árboles de la Plaça de Gaudí',array['/images/routes/sagrada-familia-diurna/plaza-gaudi.webp'],jsonb_build_object('en',jsonb_build_object('title','Plaça de Gaudí','short_description','The building within the urban landscape.','full_description','First reading of scale, framing, the square and ongoing transformation.'))),
 (v_day,'Fachada del Nacimiento',1,'Materia, naturaleza y relato.','Observamos cómo Gaudí convierte piedra, luz y formas naturales en una narración arquitectónica.',16,'Parada exterior frente a la fachada.','Pavimento urbano accesible.','Detalle de la Fachada del Nacimiento',array['/images/routes/sagrada-familia-diurna/fachada-nacimiento.webp'],jsonb_build_object('en',jsonb_build_object('title','Nativity Façade','short_description','Matter, nature and narrative.','full_description','How Gaudí turns stone, light and natural forms into architectural narrative.'))),
 (v_day,'Zona del ábside',2,'La transición entre fachadas.','Leemos estructura, continuidad y la manera en que el edificio se inserta en la manzana.',12,'Desplazamiento por acera.','Recorrido exterior urbano.','Vista contrapicada de las torres de la Sagrada Família',array['/images/routes/sagrada-familia-diurna/contrapicado-marca.webp'],jsonb_build_object('en',jsonb_build_object('title','Apse area','short_description','The transition between façades.','full_description','Structure, continuity and the building within its urban block.'))),
 (v_day,'Fachada de la Pasión',3,'Contraste, tensión y geometría.','Comparamos lenguajes arquitectónicos y la experiencia espacial de una fachada radicalmente distinta.',18,'Parada exterior.','Espacio urbano accesible.','Identificación de Rutas B ante la Sagrada Família',array['/images/routes/sagrada-familia-diurna/primer-plano-marca.webp'],jsonb_build_object('en',jsonb_build_object('title','Passion Façade','short_description','Contrast, tension and geometry.','full_description','A comparison of architectural languages and a radically different spatial experience.'))),
 (v_day,'Fachada de la Gloria',4,'La obra abierta hacia el futuro.','Cerramos relacionando proyecto, ciudad, construcción y las preguntas que permanecen abiertas.',17,'Cierre del recorrido.','Recorrido exterior urbano.','Sagrada Família y material identificativo de Rutas B',array[]::text[],jsonb_build_object('en',jsonb_build_object('title','Glory Façade','short_description','A work open to the future.','full_description','Project, city, construction and the questions that remain open.'))),
 (v_night,'Plaça de Gaudí',0,'El conjunto emerge de la oscuridad.','La distancia permite reconocer silueta, iluminación y relación con el vacío nocturno.',12,'Parada exterior nocturna.','Espacio urbano accesible.','Sagrada Família iluminada desde la Plaça de Gaudí',array['/images/routes/sagrada-familia-nocturna/fachada-nacimiento.webp'],jsonb_build_object('en',jsonb_build_object('title','Plaça de Gaudí','short_description','The complex emerges from darkness.','full_description','Distance reveals silhouette, lighting and night-time space.'))),
 (v_night,'Fachada del Nacimiento',1,'La luz selecciona el relieve.','La iluminación nocturna modifica jerarquías, sombras y detalles de la fachada.',15,'Parada exterior.','Pavimento urbano accesible.','Fachada del Nacimiento iluminada de noche',array['/images/routes/sagrada-familia-nocturna/fachada-nacimiento.webp'],jsonb_build_object('en',jsonb_build_object('title','Nativity Façade','short_description','Light selects the relief.','full_description','Night lighting changes hierarchy, shadow and detail.'))),
 (v_night,'Zona del ábside',2,'Volumen, vitrales y obra viva.','Los vitrales y la iluminación interior permiten leer el edificio como cuerpo activo.',15,'Desplazamiento por acera.','Recorrido exterior urbano.','Zona del ábside y vitrales iluminados',array['/images/routes/sagrada-familia-nocturna/zona-abside.webp'],jsonb_build_object('en',jsonb_build_object('title','Apse area','short_description','Volume, stained glass and a living work.','full_description','Stained glass and interior light reveal the building as an active body.'))),
 (v_night,'Fachada de la Pasión',3,'Escena, sombra y tensión.','La fachada adquiere una dimensión escénica donde geometría y sombra intensifican el relato.',18,'Parada exterior con apoyo audiovisual.','Espacio urbano accesible.','Fachada de la Pasión durante la noche',array['/videos/routes/sagrada-familia-nocturna/fachada-pasion.mp4'],jsonb_build_object('en',jsonb_build_object('title','Passion Façade','short_description','Scene, shadow and tension.','full_description','Geometry and shadow intensify the narrative at night.'))),
 (v_night,'Fachada de la Gloria',4,'Barcelona y el templo después de oscurecer.','El cierre conecta la experiencia nocturna con el futuro del proyecto y su entorno cotidiano.',15,'Cierre del recorrido.','Recorrido exterior urbano.','Vista nocturna de la Sagrada Família',array[]::text[],jsonb_build_object('en',jsonb_build_object('title','Glory Façade','short_description','Barcelona and the temple after dark.','full_description','The night experience connects with the future of the project and its everyday setting.')));

